// Launches headless Chrome, drives the app through REAL DOM events, captures
// screenshots + state fingerprints at every step, writes evidence/*.png|json.
import { writeFileSync, mkdirSync, rmSync } from "node:fs";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";

const ROOT = resolve(join(import.meta.dirname, ".."));
const APP_URL = "file:///" + ROOT.replace(/\\/g, "/") + "/index.html";
const OUT = join(ROOT, "evidence");
mkdirSync(OUT, { recursive: true });

const CHROME = process.env.CHROME_PATH || "C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe";
const PORT = 9333;

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function startChrome() {
  const udd = mkdtempSync(join(tmpdir(), "probe-"));
  const child = Bun // Bun not used; keep node child_process
    ? null : null;
  const { spawn } = await import("node:child_process");
  const p = spawn(CHROME, [
    "--headless=new", "--remote-debugging-port=" + PORT,
    "--user-data-dir=" + udd, "--no-first-run", "--no-default-browser-check",
    "--disable-gpu", "--hide-scrollbars", "--remote-allow-origins=*",
    "--window-size=1680,1050", "about:blank",
  ], { stdio: "ignore" });
  for (let i = 0; i < 60; i++) {
    try {
      const v = await fetch(`http://127.0.0.1:${PORT}/json/version`);
      if (v.ok) return { p, udd };
    } catch {}
    await sleep(250);
  }
  throw new Error("chrome devtools port never opened");
}

let wsId = 0;
const pending = new Map();
const consoleErrors = [];

function send(ws, method, params = {}) {
  return new Promise((res, rej) => {
    const id = ++wsId;
    pending.set(id, { res, rej });
    ws.send(JSON.stringify({ id, method, params }));
    setTimeout(() => {
      if (pending.has(id)) { pending.delete(id); rej(new Error("cdp timeout: " + method)); }
    }, 20000);
  });
}

async function evaluate(ws, expression) {
  const r = await send(ws, "Runtime.evaluate", { expression, returnByValue: true, awaitPromise: true });
  if (r.exceptionDetails) throw new Error("eval failed: " + JSON.stringify(r.exceptionDetails).slice(0, 400));
  return r.result?.value;
}

async function shot(ws, name) {
  const r = await send(ws, "Page.captureScreenshot", { format: "png" });
  writeFileSync(join(OUT, name), Buffer.from(r.data, "base64"));
}

async function key(ws, key, code, wvkc, mods = 0) {
  await send(ws, "Input.dispatchKeyEvent", { type: "keyDown", key, code, windowsVirtualKeyCode: wvkc, modifiers: mods });
