}

async function clickAt(ws, x, y) {
  await send(ws, "Input.dispatchMouseEvent", { type: "mouseMoved", x, y });
  await send(ws, "Input.dispatchMouseEvent", { type: "mousePressed", x, y, button: "left", buttons: 1, clickCount: 1 });
