    "filter cleared": Object.keys(f.filters).length === 0,
    "projection initial": f.x === "gdp" && f.y === "transit",
    "all visible again": f.visible === 240,
  }, "可回退：单击任意轨迹步恢复完整状态");
  await shot(ws, "07-jump-to-init.png");

