// Reproduce the measurement harness load to capture the pageerror stack.
import { createServer } from "node:http";
import { readFileSync, existsSync, statSync } from "node:fs";
import { join, resolve, extname } from "node:path";
import { fileURLToPath } from "node:url";
import { chromium } from "playwright";

const ROOT = resolve(join(fileURLToPath(import.meta.url), "..", ".."));
const MIME = { ".html": "text/html", ".css": "text/css", ".js": "text/javascript", ".json": "application/json", ".png": "image/png" };

const server = createServer((req, res) => {
  let p = req.url.split("?")[0];
  if (p === "/") p = "/index.html";
  const file = join(ROOT, p);
  if (existsSync(file) && statSync(file).isFile()) {
    res.writeHead(200, { "content-type": MIME[extname(file)] || "application/octet-stream" });
    res.end(readFileSync(file));
  } else {
    res.writeHead(404); res.end("nf");
  }
}).listen(12293);

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1680, height: 1050 } });
page.on("pageerror", (e) => console.log("PAGEERROR:", e.stack || e.message));
page.on("console", (m) => { if (m.type() === "error") console.log("CONSOLE ERROR:", m.text()); });
await page.goto("http://127.0.0.1:12293/index.html", { waitUntil: "load" });
await page.waitForSelector("#plot", { timeout: 10000 }).then(() => console.log("ready #plot ok")).catch((e) => console.log("ready fail:", e.message));
await page.waitForTimeout(1500);
console.log("app ready flag:", await page.evaluate("!!(window.__APP__ && window.__APP__.ready)"));
await browser.close();
server.close();

