mkdirSync(SHOTS, { recursive: true });

for (const [id, mod] of CHECKS) {
  const page = await browser.newPage({ viewport: { width: 1280, height: 860 } });
  const errors = [];
  page.on("pageerror", (e) => errors.push(e.stack || e.message));
  try {
    await page.goto(baseUrl + "index.html", { waitUntil: "load", timeout: 15000 });
    await page.locator("#plot").first().waitFor({ state: "visible", timeout: 10000 });
    const outcome = await mod.run(page, { viewport: { width: 1280, height: 860, label: "desktop" }, screenshotDir: join(SHOTS, id) });
    console.log(`${id}: ${outcome.status} ${errors.length ? "(+pageerror)" : ""}`);
    if (errors.length) console.log(errors.map((e) => "  " + e.split("\n").slice(0, 3).join("\n  ")).join("\n"));
  } catch (e) {
    console.log(`${id}: THREW ${e.message.split("\n")[0]}`);
    if (errors.length) console.log(errors.map((e2) => "  pageerror-stack: " + e2.split("\n").slice(0, 4).join(" | ")).join("\n"));
  }
  await page.close();
}
await browser.close();
server.close();

