// Per-check reproduction of prax-measure flow with pageerror stack logging.
import { createServer } from "node:http";
import { readFileSync, existsSync, statSync, mkdirSync } from "node:fs";
import { join, resolve, extname } from "node:path";
import { fileURLToPath } from "node:url";
import { chromium } from "file:///E:/codex-prj/pi-m3-frozen-runtime-r3-20260918/node_modules/playwright/index.mjs";

const PM = "file:///E:/codex-prj/pi-m3-frozen-runtime-r3-20260918/packages/prax-measure/dist/checks/";
const CHECKS = [
  ["layout.overflow", await import(PM + "layout.overflow.js")],
  ["layout.responsive_collision", await import(PM + "layout.responsive_collision.js")],
  ["text.truncation", await import(PM + "text.truncation.js")],
  ["a11y.contrast", await import(PM + "a11y.contrast.js")],
  ["a11y.focus_order", await import(PM + "a11y.focus_order.js")],
  ["a11y.target_size", await import(PM + "a11y.target_size.js")],
  ["type.min_projected_size", await import(PM + "type.min_projected_size.js")],
];

const ROOT = resolve(join(fileURLToPath(import.meta.url), "..", ".."));
const MIME = { ".html": "text/html; charset=utf-8", ".css": "text/css", ".js": "text/javascript; charset=utf-8", ".json": "application/json", ".png": "image/png" };
const server = createServer((req, res) => {
  let p = decodeURIComponent(req.url.split("?")[0]);
  if (p.endsWith("/")) p += "index.html";
  const file = join(ROOT, p);
  try {
    if (existsSync(file) && statSync(file).isFile()) {
      res.writeHead(200, { "content-type": MIME[extname(file)] || "application/octet-stream" });
      res.end(readFileSync(file));
    } else { res.writeHead(404); res.end("nf"); }
  } catch { res.writeHead(404); res.end("nf"); }
}).listen(0, "127.0.0.1");
await new Promise((r) => server.once("listening", r));
const baseUrl = `http://127.0.0.1:${server.address().port}/`;

const browser = await chromium.launch();
const SHOTS = join(ROOT, "evidence", "check-shots");
mkdirSync(SHOTS, { recursive: true });

for (const [id, mod] of CHECKS) {
  const page = await browser.newPage({ viewport: { width: 1280, height: 860 } });
  const errors = [];
  page.on("pageerror", (e) => errors.push(e.stack || e.message));
  try {
    await page.goto(baseUrl + "index.html", { waitUntil: "load", timeout: 15000 });
    await page.locator("#plot").first().waitFor({ state: "visible", timeout: 10000 });
    const outcome = await mod.run(page, { viewport: { width: 1280, height: 860, label: "desktop" }, screenshotDir: join(SHOTS, id) });
    console.log(`${id}: ${outcome.status} ${errors.length ? "(+pageerror)" : ""}`);
    if (errors.length) console.log(errors.map((e) => "  " + e.split("\n").slice(0, 3).join("\n  ")).join("\n"));
  } catch (e) {
    console.log(`${id}: THREW ${e.message.split("\n")[0]}`);
    if (errors.length) console.log(errors.map((e2) => "  pageerror-stack: " + e2.split("\n").slice(0, 4).join(" | ")).join("\n"));
  }
  await page.close();
}
await browser.close();
server.close();

